Set-StrictMode -Version Latest
$ErrorActionPreference = 'Stop'

$W = 34  # interior width
function Box([string]$t) {
    $t = $t.TrimEnd()
    $pad = $W - $t.Length
    if ($pad -lt 0) { throw "Too long: '$t'" }
    $left = [int][math]::Floor($pad / 2)
    $right = $pad - $left
    return '|' + (' ' * $left) + $t + (' ' * $right) + '|'
}
$border = '+' + ('=' * $W) + '+'

$lines = @(
    $border
    Box 'TASKFORGE'
    Box 'STATS  DASHBOARD'
    $border
    Box 'TOTAL   PENDING   COMPLETED'
    Box '=====   =======   ========='
    Box '* TASKS BY UTC CALENDAR DATE *'
    Box '#### ____ #### ____ #### ____'
    Box 'PROGRESS (COMPLETED / TOTAL)'
    Box 'RATE .... ONE DECIMAL PLACE'
    Box 'READ-ONLY :: NO WRITES HERE'
    $border
)

if ($lines.Count -ne 12) { throw "Expected 12 lines, got $($lines.Count)" }

$allowed = [System.Collections.Generic.HashSet[char]]::new()
foreach ($c in ([char[]]"ABCDEFGHIJKLMNOPQRSTUVWXYZ0123456789+|/\_*.#(): =-")) { [void]$allowed.Add($c) }

$i = 0
foreach ($ln in $lines) {
    $i++
    if ($ln.Length -lt 20 -or $ln.Length -gt 48) { throw "Line $i length $($ln.Length) out of 20-48: '$ln'" }
    if ($ln -ne $ln.TrimEnd()) { throw "Line $i has trailing whitespace" }
    foreach ($ch in [char[]]$ln) {
        if ([int]$ch -gt 127) { throw "Line $i non-ASCII" }
        if (-not $allowed.Contains($ch)) { throw "Line $i disallowed char '$ch'" }
    }
}
$joined = ($lines -join "`n")
if ($joined -notmatch 'STATS') { throw "Missing literal STATS" }

$assetDir = Join-Path (Split-Path -Parent $PSScriptRoot) 'assets'
# We instead target the repo path passed as arg
$outPath = $args[0]
$parent = Split-Path -Parent $outPath
if (-not (Test-Path -LiteralPath $parent)) { New-Item -ItemType Directory -Path $parent -Force | Out-Null }
$text = $joined + "`n"
[System.IO.File]::WriteAllText($outPath, $text, [System.Text.UTF8Encoding]::new($false))
Write-Host "Wrote $outPath ($($lines.Count) lines)"
$lines | ForEach-Object { "{0,2}: [{1,2}] {2}" -f (++$script:n), $_.Length, $_ }

